"""Add RunOn's service to the formula generated by cargo-dist."""

from pathlib import Path
import sys


SERVICE_AND_TEST = """
  service do
    run opt_bin/"runon"
    keep_alive successful_exit: false
    stop_timeout 5
    environment_variables HOME: Dir.home
    error_log_path var/"log/runon.log"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/runon --version")
  end
"""


def prepare(formula):
    license_line = '  license "MIT"\n'
    if (
        not formula.startswith("class Runon < Formula\n")
        or not formula.endswith("\nend\n")
        or formula.count(license_line) != 1
        or "  service do\n" in formula
    ):
        raise ValueError("unexpected cargo-dist RunOn formula; refusing to publish")
    formula = formula.replace(
        license_line, license_line + "\n  depends_on macos: :sequoia\n", 1
    )
    return formula.removesuffix("end\n") + SERVICE_AND_TEST + "end\n"


if __name__ == "__main__":
    path = Path(sys.argv[1])
    path.write_text(prepare(path.read_text()))
